      isRegionSelectActive ? 'viewport-region-select' : '',
    ]"
    @pointerdown="focusViewportContainer"
  >
    <canvas ref="canvasRef" class="viewport-canvas block w-full h-full" />
    <ViewportOverlay :get-camera-quaternion="getCameraQuaternion" />
    <!--
