import { defineStore } from 'pinia'
import { ref } from 'vue'
import type { PanelId } from '../types/editor'

export const usePanelsStore = defineStore('panels', () => {
  const visibility = ref<Record<PanelId, boolean>>({
    hierarchy: true,
    assets: true,
    inspector: true,
  })

  const collapsed = ref<Record<PanelId, boolean>>({
    hierarchy: false,
    assets: false,
    inspector: false,
  })

  function toggleVisibility(panel: PanelId) {
    visibility.value[panel] = !visibility.value[panel]
  }

  function toggleCollapsed(panel: PanelId) {
    collapsed.value[panel] = !collapsed.value[panel]
  }

  function setVisibility(panel: PanelId, visible: boolean) {
    visibility.value[panel] = visible
  }

  return {
    visibility,
    collapsed,
    toggleVisibility,
    toggleCollapsed,
    setVisibility,
  }
})
