import type * as THREE from 'three'
import type { ViewerSDK, RendererModuleState, CameraModuleState } from '@tencent/viewer-sdk'
import { getModule, rendererModule, cameraModule } from '@tencent/viewer-sdk'

/**
 * 从 ViewerSDK 一次取到当前 THREE 三件套 + domElement，用于 selection / transform / picker
 * 等交互能力初始化时的一次性快照拉取。
 *
 * ⚠️ 返回结果是 ECS state 的引用，调用方**必须**在使用前 null 守卫；同时**不应**长时间持有
 *    （相机切换 / 渲染器重建时 ECS state 内字段会重新赋值，缓存引用可能失效）。
 *
 * @param sdk ViewerSDK 实例（可能为 null，未就绪时返回 null 三件套）
 * @returns 三件套快照；任一字段为 null 表示 ECS state 未就绪或该模块未装配
 */
export interface SdkThreeContext {
  scene: THREE.Scene | null
  camera: THREE.PerspectiveCamera | null
  renderer: THREE.WebGLRenderer | null
  domElement: HTMLCanvasElement | null
}

export function getSdkThreeContext(sdk: ViewerSDK | null): SdkThreeContext {
  const empty: SdkThreeContext = { scene: null, camera: null, renderer: null, domElement: null }
  if (!sdk) return empty

  const ctx = sdk.getSceneManager()?.ctx
  if (!ctx) return empty

  try {
    const rendererState = getModule<RendererModuleState>(ctx, rendererModule)
    const cameraState = getModule<CameraModuleState>(ctx, cameraModule)
    return {
      scene: rendererState?.scene ?? null,
      camera: cameraState?.camera ?? null,
      renderer: rendererState?.renderer ?? null,
      domElement: rendererState?.renderer?.domElement ?? null,
    }
  } catch {
    return empty
  }
}

/**
 * 便捷单项 getter，用于只需要相机/场景等单一字段的场景（如 Viewport.vue 的 computeFocusCameraState
 * 只需要相机）。内部复用 getSdkThreeContext 的 try/catch 守卫，语义等价。
 */
export function getSdkCamera(sdk: ViewerSDK | null): THREE.PerspectiveCamera | null {
  return getSdkThreeContext(sdk).camera
}

export function getSdkScene(sdk: ViewerSDK | null): THREE.Scene | null {
  return getSdkThreeContext(sdk).scene
}

export function getSdkDomElement(sdk: ViewerSDK | null): HTMLCanvasElement | null {
  return getSdkThreeContext(sdk).domElement
}
