/**
 * useAutoDraft — 标注草稿自动存档 composable
 *
 * 监听 sceneConfig 变化，防抖 800ms 后自动写入 localStorage 草稿。
 *
 * 防抖 800ms 的设计依据：
 *   · InspectorPanel 文本框输入时每按一键触发 updateProp → watch
 *   · 800ms 能有效合并连续键盘输入，避免 localStorage 每帧都写
 *   · Gizmo live 拖拽不写 store → watch 不触发 → 不写草稿（零开销）
 *   · 松手后 store 写入一次 → 防抖 800ms 后写草稿（单次写入）
 *
 * 在 SplatStudio.vue 顶层调用一次即可，无需传参。
 *
 * @changelog
 * | 版本   | 变更说明                                          | 关联               |
 * | v1.0.0 | 初始实现：watch(sceneConfig) + 防抖 800ms → saveDraft | REQ: 标注草稿自动存档 |
 * /@changelog
 *
 * @author v_djlzhou
 */
import { watch, onUnmounted } from 'vue'
import { useSceneStore } from '../stores/scene'

export function useAutoDraft(): void {
  const sceneStore = useSceneStore()
  let timer: ReturnType<typeof setTimeout> | null = null

  const stopWatch = watch(
    () => sceneStore.sceneConfig,
    () => {
      // 无加载场景时不存档（sceneConfig 可能是空白默认值）
      if (!sceneStore.sdkSceneUrl) return
      if (timer) clearTimeout(timer)
      timer = setTimeout(() => {
        timer = null
        sceneStore.saveDraft()
      }, 800)
    },
    { deep: true },
  )

  onUnmounted(() => {
    stopWatch()
    if (timer) {
      clearTimeout(timer)
      timer = null
    }
  })
}
