import type { UseTransformProxyHandle } from './useTransformProxy'

export type EditableConfigSelection =
  | { kind: 'floor'; id: string }
  | { kind: 'prop'; id: string }
  | { kind: 'meta' }
  | null

interface FlyCameraControllerLike {
  isEnabled?: () => boolean
  setEnabled: (enabled: boolean) => void
}

export interface UseModalAxisDragOptions {
  sdk: ShallowRef<ViewerSDK | null>
  activeTool: Readonly<Ref<ToolType>>
  axisLock: Readonly<Ref<AxisLock>>
  /**
   * 【v1.1.0】变换坐标系。仅在 translate 模式下起作用：
   *   · 'world' → 沿世界轴（X/Y/Z 固定方向）
   *   · 'local' → 沿物体本地轴（proxyGroup.matrixWorld 对应列向量）
   * scale 模式由业务约束永远 local（see editor store toggleTransformSpace 守卫）；
   * 这里即便传 'world' 也会被本模块 scale 分支忽略。
   */
  transformSpace: Readonly<Ref<TransformSpace>>
  selectedConfigKey: Readonly<Ref<EditableConfigSelection>>
  /** 只读的 floor/prop 查询 —— 用于线框命中判定（拿到 OBB 尺寸/位置）。不写入 */
  getFloor: (id: string) => FloorConfigItem | undefined
  getProp: (id: string) => PropConfigItem | undefined
  /**
   * useTransformProxy 暴露的原语集合（PRD §5.1）。
   * 所有代理盒的 snapshot / 写入 / commit 通过此句柄完成，不绕过 sceneStore 链路。
   */
  transformProxy: UseTransformProxyHandle
}

export interface UseModalAxisDragHandle {
  dispose: () => void
  /**
   * 判断给定 PointerEvent 是否命中当前选中物体的 OBB 线框（含 6px 容差）。
   *
   * 供 Viewport 的"空白处清选"逻辑查询——命中线框时不应触发清选。
   * 需要已有 selectedConfigKey + SDK 就绪；未就绪时返回 false（保守：不清选）。
   */
  isPointerOnHighlight: (e: PointerEvent) => boolean
}

/** 拖拽阈值：超过此 px 才视为真实拖拽（防误触，避免短点击被识别为 0 距拖拽） */
const DRAG_THRESHOLD_PX = 3

/**
 * 线框命中容差（CSS 像素）。
 *
 * floor 是扁平盒子（minY≈maxY）——屏幕投影多边形在俯视 / 轻微俯角下
 * 退化成近似"一条窄带"，没有容差几乎按不上。prop 通常有真实高度，
 * 基本不需要容差，但统一给 6px 有益无害。
 *
 * 6px 经验值：按钮 / 窗口边框的典型"手指友好命中"是 8px，这里稍小避免
 * 吞掉相邻空白区的相机拖动意图。
 */
const HIGHLIGHT_HIT_TOLERANCE_PX = 6

export function useModalAxisDrag(options: UseModalAxisDragOptions): UseModalAxisDragHandle {
  let domElement: HTMLElement | null = null
  let camera: THREE.PerspectiveCamera | null = null
  let flyCameraController: FlyCameraControllerLike | null = null

  /**
   * 拖拽运行时状态。不用 reactive：高频 pointermove 期间避免 Vue 的依赖追踪开销。
   */
  let dragging = false
  let armed = false // pointerdown 已命中 + snapshot 完成，但未越过阈值
  let downX = 0
  let downY = 0
  /**
   * 【v1.1.0】当前激活的拖拽模式。pointerdown 时根据 activeTool 锁定，
   * 拖拽期间即便快捷键切换工具也不会改变（PRD §4.2"拖拽期间不响应快捷键切换"）。
   * 【v1.3.0】新增 'rotate' 分支。
   */
  let activeMode: 'translate' | 'scale' | 'rotate' = 'translate'

  /* --- translate 分支专用 --- */
  const startPos = new THREE.Vector3() // 物体起始世界位置（来自 proxyGroup.position）
  const axisDirWorld = new THREE.Vector3() // 锁定的世界轴方向（world 轴 或 local→world 的倾斜方向）
  const dragPlane = new THREE.Plane() // 拖拽平面：含 startPos、含 axis、正对相机
  const downHitWorld = new THREE.Vector3() // 按下时的鼠标-平面交点（拖拽锚点）

  /* --- scale 分支专用（v1.1.0） --- */
  const baseScale = new THREE.Vector3() // 物体 snapshot 时的 scale（各轴基准值）
  const screenCenter = { x: 0, y: 0 } // 物体 pointerdown 时的屏幕投影中心（canvas-rect-relative CSS 像素）
  let distStartPx = 0 // pointerdown 时鼠标到 screenCenter 的像素距离

  /* --- rotate 分支专用（v1.3.0） --- */
  let baseYaw = 0 // pointerdown 时物体的 yaw（弧度，来自 getYawFromQuaternion）
  let startScreenAngle = 0 // pointerdown 时鼠标相对 screenCenter 的屏幕角度（弧度）

  const scratch: AxisProjectionScratch = createAxisProjectionScratch()

  /**
   * 拖拽中 FlyCamera 的原始启用态备份。pointerdown 成功时读取并禁用相机，
   * pointerup / ESC / 右键取消 时恢复。与 useTransformProxy 互不干扰（两者不会同时 armed）。
   */
  let wasFlyCameraEnabledBeforeDrag = false

  /* ============================================================
   * Cursor 状态（锁轴 hover 反馈）
   *
   * 模式：
   *   null       → 清空 cursor，交给 CSS 默认
   *   'grab'     → 小手（move 模式：锁轴 + 悬停在线框内）
   *   'grabbing' → 抓取中（move 模式拖拽）
   *   'rotate-arc' → 圆弧双向箭头（rotate 模式：hover + 拖拽中）
   *   { kind: 'axis-arrow', angleQ } → scale 模式双向箭头
   *     · angleQ 是 5° 量化后的 0..355 角度
   *     · hover 和 dragging 使用同一套箭头（视觉不区分按下态）
   * ============================================================ */
  type CursorMode =
    | null
    | 'grab'
    | 'grabbing'
    | 'rotate-arc'
    | { kind: 'axis-arrow'; angleQ: number }
  let currentCursor: CursorMode = null
  /** dist < 2px 时沿用上一帧箭头角度（避免奇异点抖动） */
  let lastArrowAngleDeg = 0

  function setCursor(mode: CursorMode): void {
    // 早退：类型 + 内容都相同则跳过
    if (cursorEquals(mode, currentCursor)) return
    if (!domElement) {
      currentCursor = mode
      return
    }
    if (mode === null) {
      domElement.style.cursor = ''
    } else if (mode === 'grab') {
      domElement.style.cursor = 'grab'
    } else if (mode === 'grabbing') {
      domElement.style.cursor = 'grabbing'
    } else if (mode === 'rotate-arc') {
      domElement.style.cursor = getRotateCursor()
    } else {
      // axis-arrow：通过 dataURL 生成箭头 cursor
      domElement.style.cursor = getAxisArrowCursor(mode.angleQ)
    }
    currentCursor = mode
  }

  function cursorEquals(a: CursorMode, b: CursorMode): boolean {
    if (a === b) return true
    if (a === null || b === null) return false
    if (typeof a === 'string' || typeof b === 'string') return a === b
    return a.kind === b.kind && a.angleQ === b.angleQ
  }

  /**
   * 计算鼠标相对给定 CSS 中心的角度（度）。
   * 距离 < 2px 时返回 null，让调用方沿用上一帧角度，避免零点附近抖动。
   */
  function computeArrowAngle(
    mouseCssX: number,
    mouseCssY: number,
    centerCssX: number,
    centerCssY: number,
  ): number | null {
    const dx = mouseCssX - centerCssX
    const dy = mouseCssY - centerCssY
    const dist = Math.hypot(dx, dy)
    if (dist < 2) return null
    // atan2 返回弧度；Y 轴 CSS 向下为正，SVG rotate 也是顺时针为正，符号一致无需翻转
    return (Math.atan2(dy, dx) * 180) / Math.PI
  }

  /* ============================================================
   * SDK 句柄装载（懒加载，每次 pointerdown 时拉一次最新引用）
   * ============================================================ */

  function pullRuntime(): boolean {
    const sdk = options.sdk.value
    if (!sdk) return false
    // v: 从 helper 一次拿相机 + domElement（ECS 直读 rendererModule/cameraModule state）
    const { camera: cam, domElement: dom } = getSdkThreeContext(sdk)
    if (!cam || !(cam instanceof THREE.PerspectiveCamera) || !dom) return false
    camera = cam
    domElement = dom
    flyCameraController =
      (sdk
        .getSceneManager()
        ?.getCreativeModeManager()
        ?.getFlyCameraController() as FlyCameraControllerLike | null) ?? null
    return true
  }

  /* ============================================================
   * 线框命中判定（OBB 8 角 → CSS → 凸包 + 容差）
   *
   * 几何口径（与 Viewport.vue 的 floorToAABB / propToAABB 完全一致）：
   *   floor: center=(px, py+0.01, pz), half=(w/2, 0.01, d/2), rotY=rad(rotation.y ?? 0)
   *   prop:  center=(px, py+h/2,  pz), half=(w/2, h/2,  d/2), rotY=rad(rotation.y)
   * ============================================================ */

  const _worldCorners: THREE.Vector3[] = Array.from({ length: 8 }, () => new THREE.Vector3())
  const _cssX: number[] = new Array(8).fill(0)
  const _cssY: number[] = new Array(8).fill(0)
  const _projectTmp = new THREE.Vector3()

  function build8WorldCorners(
    cx: number,
    cy: number,
    cz: number,
    hx: number,
    hy: number,
    hz: number,
    rotYRad: number,
    out: THREE.Vector3[],
  ): void {
    const cos = Math.cos(rotYRad)
    const sin = Math.sin(rotYRad)
    let i = 0
    for (const sx of [-1, 1]) {
      for (const sy of [-1, 1]) {
        for (const sz of [-1, 1]) {
          const lx = sx * hx
          const ly = sy * hy
          const lz = sz * hz
          const wx = lx * cos - lz * sin + cx
          const wz = lx * sin + lz * cos + cz
          out[i++].set(wx, cy + ly, wz)
        }
      }
    }
  }

  function project8ToCss(
    worldPts: THREE.Vector3[],
    outX: number[],
    outY: number[],
    halfW: number,
    halfH: number,
  ): boolean {
    if (!camera) return false
    for (let i = 0; i < 8; i++) {
      _projectTmp.copy(worldPts[i]).project(camera)
      if (_projectTmp.z < -1 || _projectTmp.z > 1) return false
      outX[i] = (_projectTmp.x + 1) * halfW
      outY[i] = (1 - _projectTmp.y) * halfH
    }
    return true
  }

  /**
   * 8 点凸包（Andrew's monotone chain），产出逆时针点序列。
   * 调用方用叉积同号法做"点在凸多边形内"判定。
   */
  function convexHull(xs: number[], ys: number[]): Array<[number, number]> {
    const pts: Array<[number, number]> = []
    for (let i = 0; i < 8; i++) pts.push([xs[i], ys[i]])
    pts.sort((a, b) => (a[0] === b[0] ? a[1] - b[1] : a[0] - b[0]))
    const cross = (
      o: [number, number],
      a: [number, number],
      b: [number, number],
    ): number => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    const lower: Array<[number, number]> = []
    for (const p of pts) {
      while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], p) <= 0) {
        lower.pop()
      }
      lower.push(p)
    }
    const upper: Array<[number, number]> = []
    for (let i = pts.length - 1; i >= 0; i--) {
      const p = pts[i]
      while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], p) <= 0) {
        upper.pop()
      }
      upper.push(p)
    }
    lower.pop()
    upper.pop()
    return lower.concat(upper)
  }

  function distToSegment(
    px: number,
    py: number,
    ax: number,
    ay: number,
    bx: number,
    by: number,
  ): number {
    const dx = bx - ax
    const dy = by - ay
    const lenSq = dx * dx + dy * dy
    if (lenSq < 1e-9) return Math.hypot(px - ax, py - ay)
    let t = ((px - ax) * dx + (py - ay) * dy) / lenSq
    if (t < 0) t = 0
    else if (t > 1) t = 1
    return Math.hypot(px - (ax + t * dx), py - (ay + t * dy))
  }

  function pointInHullWithTolerance(
    hull: Array<[number, number]>,
    px: number,
    py: number,
    tolerance: number,
  ): boolean {
    const n = hull.length
    if (n < 2) return false

    if (n >= 3) {
      let sign = 0
      let inside = true
      for (let i = 0; i < n; i++) {
        const [ax, ay] = hull[i]
        const [bx, by] = hull[(i + 1) % n]
        const cross = (bx - ax) * (py - ay) - (by - ay) * (px - ax)
        if (cross !== 0) {
          const s = cross > 0 ? 1 : -1
          if (sign === 0) sign = s
          else if (sign !== s) {
            inside = false
            break
          }
        }
      }
      if (inside) return true
    }

    let minDist = Infinity
    for (let i = 0; i < n; i++) {
      const [ax, ay] = hull[i]
      const [bx, by] = hull[(i + 1) % n]
      const d = distToSegment(px, py, ax, ay, bx, by)
      if (d < minDist) minDist = d
    }
    return minDist <= tolerance
  }

  function isPointerOnHighlight(e: PointerEvent): boolean {
    if (!camera || !domElement) return false
    const sel = options.selectedConfigKey.value
    if (!sel || sel.kind === 'meta') return false

    let cx: number, cy: number, cz: number, hx: number, hy: number, hz: number, rotY: number
    if (sel.kind === 'floor') {
      const f = options.getFloor(sel.id)
      if (!f) return false
      cx = f.position.x
      cy = f.position.y + 0.01
      cz = f.position.z
      hx = f.dimensions.width / 2
      hy = 0.01
      hz = f.dimensions.depth / 2
      rotY = THREE.MathUtils.degToRad(f.rotation?.y ?? 0)
    } else {
      const p = options.getProp(sel.id)
      if (!p) return false
      cx = p.position.x
      cy = p.position.y + p.dimensions.y / 2
      cz = p.position.z
      hx = p.dimensions.x / 2
      hy = p.dimensions.y / 2
      hz = p.dimensions.z / 2
      rotY = THREE.MathUtils.degToRad(p.rotation?.y ?? 0)
    }

    const rect = domElement.getBoundingClientRect()
    const halfW = rect.width / 2
    const halfH = rect.height / 2

    build8WorldCorners(cx, cy, cz, hx, hy, hz, rotY, _worldCorners)
    if (!project8ToCss(_worldCorners, _cssX, _cssY, halfW, halfH)) {
      return false
    }

    const hull = convexHull(_cssX, _cssY)
    const px = e.clientX - rect.left
    const py = e.clientY - rect.top
    return pointInHullWithTolerance(hull, px, py, HIGHLIGHT_HIT_TOLERANCE_PX)
  }

  /* ============================================================
   * Hover cursor 反馈（锁轴状态下指示"可抓取"）
   *
   * move 模式：grab / null
   * scale 模式：双向箭头（沿"中心→鼠标"方向） / null
   *   · floor + 锁 Y 业务无效 → null（不暗示可拖）
   * ============================================================ */
  function onHoverMove(e: PointerEvent): void {
    if (armed) return
    if (!shouldEngage()) {
      setCursor(null)
      return
    }
    if (!pullRuntime()) {
      setCursor(null)
      return
    }

    const onHighlight = isPointerOnHighlight(e)
    if (!onHighlight) {
      setCursor(null)
      return
    }

    const tool = options.activeTool.value
    const lock = options.axisLock.value

    if (tool === 'rotate') {
      // rotate + 锁轴（业务只允许锁 Y）+ 命中线框 → 圆弧箭头
      // floor + rotate：resolveTransformMode 降级为 translate，shouldEngage 已排除，不会到这里
      setCursor('rotate-arc')
      return
    }

    if (tool === 'scale') {
      // floor + 锁 Y：业务无效（sanitizeProxyTransform 会把 scale.y 钉死为 FLOOR_PROXY_THICKNESS）
      const sel = options.selectedConfigKey.value
      if (sel?.kind === 'floor' && lock === 'Y') {
        setCursor(null)
        return
      }

      // 投影线框原点到 CSS
      const proxy = options.transformProxy.getProxyGroup()
      if (!proxy || !camera || !domElement) {
        setCursor(null)
        return
      }
      const center = { x: 0, y: 0 }
      if (!projectWorldToScreen(camera, proxy.position, domElement, center, scratch)) {
        // 物体在视锥外 → 不显示箭头
        setCursor(null)
        return
      }

      const rect = domElement.getBoundingClientRect()
      const px = e.clientX - rect.left
      const py = e.clientY - rect.top
      const angle = computeArrowAngle(px, py, center.x, center.y)
      if (angle !== null) lastArrowAngleDeg = angle
      // angle === null（dist<2px）→ 沿用上一帧角度，不清空 cursor
      setCursor({ kind: 'axis-arrow', angleQ: quantizeAngleDeg(lastArrowAngleDeg) })
      return
    }

    // move 模式：保持原有 grab
    setCursor('grab')
  }

  /* ============================================================
   * 入口条件
   *
   * 【v1.3.0】作用域扩展：translate（move 工具）+ scale + rotate + 已锁轴 + 已选中 floor/prop。
   * select / region-select 也不响应。
   * ============================================================ */
  function shouldEngage(): boolean {
    const tool = options.activeTool.value
    if (tool !== 'move' && tool !== 'scale' && tool !== 'rotate') return false
    if (options.axisLock.value === null) return false
    const sel = options.selectedConfigKey.value
    if (!sel || sel.kind === 'meta') return false
    return true
  }

  /* ============================================================
   * 事件处理
   * ============================================================ */

  function onPointerDown(e: PointerEvent): void {
    if (e.button !== 0) return
    if (!shouldEngage()) return
    if (!pullRuntime()) return

    /* ----------------------------------------------------------
     * Gizmo 手柄优先：若 TransformControls 已经把本次 pointerdown 识别为"命中手柄"
     * 并进入 dragging 态，我们必须静默放行 —— 避免两者同时写 proxyGroup 冲突。
     *
     * TC 内部在自己的 pointerdown 监听里同步设置 dragging=true（先于我们，因为两个
     * 监听都挂在同一 dom，但 TC 在 capture 阶段先注册 or 先命中 raycaster）。
     * 实测：如果 TC 命中手柄，我们的 capture listener 会收到 stopImmediatePropagation
     * 而根本跑不到；但为了"不依赖 TC 实现细节"，这里再加一道保险。
     * ---------------------------------------------------------- */
    if (options.transformProxy.isGizmoDragging()) return

    /* ----------------------------------------------------------
     * 线框命中判定：只有按在"选中物体的 OBB 屏幕投影"（+6px 容差）上才开拖。
     * 不命中时**不 preventDefault / 不 stopPropagation** —— 本 listener 在 capture
     * 阶段不做任何事 = 天然放行（FlyCameraController 在 bubble 阶段按原流程接管）。
     * ---------------------------------------------------------- */
    if (!isPointerOnHighlight(e)) return

    /* ----------------------------------------------------------
     * 读 proxyGroup 作为起始 anchor。
     *
     * 为什么不直接读 floor/prop.position：代理盒的 position 才是"Gizmo 看到的
     * 当前变换"，理论上应该和 floor/prop.position 一致，但如果用户正在数值输入
     * 面板里改但还没提交，proxyGroup 是更可信的瞬时源。
     * ---------------------------------------------------------- */
    const proxy = options.transformProxy.getProxyGroup()
    const sel = options.transformProxy.getActiveSelection()
    if (!proxy || !sel) return

    // sanity check: 代理当前挂在哪个物体上必须和 selectedConfigKey 一致
    const selKey = options.selectedConfigKey.value
    if (!selKey || selKey.kind === 'meta') return
    if (selKey.kind !== sel.kind || selKey.id !== sel.id) return

    const lock = options.axisLock.value
    if (lock === null) return
    if (!camera || !domElement) return

    /* ----------------------------------------------------------
     * 锁定工具对应的拖拽模式（拖拽期间不受快捷键切换影响 —— PRD §4.2）
     * ---------------------------------------------------------- */
    const tool = options.activeTool.value
    if (tool !== 'move' && tool !== 'scale' && tool !== 'rotate') return
    if (tool === 'rotate') activeMode = 'rotate'
    else if (tool === 'scale') activeMode = 'scale'
    else activeMode = 'translate'

    /* ----------------------------------------------------------
     * floor + scale + 锁 Y：按业务约束无效（floor 无 height 字段，
     * sanitizeProxyTransform 会把 scale.y 钉死为 FLOOR_PROXY_THICKNESS）。
     * 此时直接放行，不拦截 pointerdown，让 FlyCamera 接管。
     * ---------------------------------------------------------- */
    if (activeMode === 'scale' && selKey.kind === 'floor' && lock === 'Y') return

    /* ----------------------------------------------------------
     * 分支准备
     * ---------------------------------------------------------- */
    if (activeMode === 'translate') {
      startPos.copy(proxy.position)

      /* 构造轴方向：world 用固定单位向量；local 用 proxy.matrixWorld 的对应列（已归一化去除 scale） */
      // 保证 matrixWorld 最新（Vue render cycle 外 / pointermove 外部写入时可能未 update）
      proxy.updateMatrixWorld(true)
      if (options.transformSpace.value === 'local') {
        writeAxisLocalVector(lock, proxy.matrixWorld, axisDirWorld)
      } else {
        writeAxisUnitVector(lock, axisDirWorld)
      }

      if (!buildDragPlaneFromDir(camera, axisDirWorld, startPos, dragPlane, scratch)) {
        console.warn(
          `[modal-axis-drag] 退化：${options.transformSpace.value} ${lock} 轴与相机 forward 近乎平行，中断拖拽。请旋转视角后重试。`,
        )
        return
      }

      // 按下锚点 = 鼠标射线 ∩ dragPlane（取 scratch.tmpHit 的副作用作为真实 3D 交点）
      const anchorDelta = projectPointerToAxis(
        camera,
        domElement,
        e.clientX,
        e.clientY,
        dragPlane,
        axisDirWorld,
        startPos, // 临时用 startPos 做 anchor，算出来的 Δ 不用，只要 scratch.tmpHit 副作用
        scratch,
      )
      if (anchorDelta === null) {
        console.warn('[modal-axis-drag] 退化：按下点鼠标射线与拖拽平面无交点，中断拖拽。')
        return
      }
      downHitWorld.copy(scratch.tmpHit)
    } else if (activeMode === 'scale') {
      // scale 分支
      baseScale.copy(proxy.scale)
      // 物体屏幕投影中心（即 proxyGroup.position 投到 CSS 像素）
      if (!projectWorldToScreen(camera, proxy.position, domElement, screenCenter, scratch)) {
        console.warn('[modal-axis-drag] 退化：物体位于相机裁剪平面外，无法做 scale 距离比。')
        return
      }
      const rect = domElement.getBoundingClientRect()
      const px = e.clientX - rect.left
      const py = e.clientY - rect.top
      distStartPx = Math.hypot(px - screenCenter.x, py - screenCenter.y)
      // distStartPx < 5px 不中断，后续 computeScaleFactor 会走线性退化模式
    } else {
      // rotate 分支（v1.3.0）
      baseYaw = getYawFromQuaternion(proxy.quaternion)
      // 物体屏幕投影中心
      if (!projectWorldToScreen(camera, proxy.position, domElement, screenCenter, scratch)) {
        console.warn('[modal-axis-drag] 退化：物体位于相机裁剪平面外，无法做 rotate。')
        return
      }
      const rect = domElement.getBoundingClientRect()
      const px = e.clientX - rect.left
      const py = e.clientY - rect.top
      startScreenAngle = Math.atan2(py - screenCenter.y, px - screenCenter.x)
    }

    /* ----------------------------------------------------------
     * 阻断相机事件合成：preventDefault + stopPropagation，阻止浏览器合成
     * 后续 mousedown/mousemove/mouseup，也阻止其他 pointer 监听接管。
     * ---------------------------------------------------------- */
    e.preventDefault()
    e.stopPropagation()
    e.stopImmediatePropagation()

    /* ----------------------------------------------------------
     * snapshot：让 useTransformProxy 记下当前 proxy 状态，供 ESC 回滚
     * ---------------------------------------------------------- */
    options.transformProxy.captureSnapshot()

    /* ----------------------------------------------------------
     * 禁用 FlyCamera（Blender-like：锁轴拖拽期间 WASD 不应移动相机）
     * ---------------------------------------------------------- */
    if (flyCameraController) {
      wasFlyCameraEnabledBeforeDrag = flyCameraController.isEnabled?.() ?? true
      flyCameraController.setEnabled(false)
    }

    armed = true
    dragging = false
    downX = e.clientX
    downY = e.clientY

    // v1.2.0：scale 用箭头 cursor（角度此时以鼠标-中心为准），move 维持 grabbing，
    // v1.3.0：rotate 用圆弧箭头 cursor
    if (activeMode === 'scale') {
      const rect = domElement.getBoundingClientRect()
      const px = e.clientX - rect.left
      const py = e.clientY - rect.top
      const angle = computeArrowAngle(px, py, screenCenter.x, screenCenter.y)
      if (angle !== null) lastArrowAngleDeg = angle
      setCursor({ kind: 'axis-arrow', angleQ: quantizeAngleDeg(lastArrowAngleDeg) })
    } else if (activeMode === 'rotate') {
      setCursor('rotate-arc')
    } else {
      setCursor('grabbing')
    }

    window.addEventListener('pointermove', onPointerMove, true)
    window.addEventListener('pointerup', onPointerUp, true)
    window.addEventListener('keydown', onKeyDown, true)
    window.addEventListener('contextmenu', onContextMenu, true)

    // 吞噬 mouse* 合成事件，阻止 FlyCameraController（用 mousedown/move/up 监听）接管
    window.addEventListener('mousedown', swallowMouse, true)
    window.addEventListener('mousemove', swallowMouse, true)
    window.addEventListener('mouseup', swallowMouse, true)
  }

  function swallowMouse(e: MouseEvent): void {
    if (!armed) return
    e.stopPropagation()
    e.stopImmediatePropagation()
  }

  function onPointerMove(e: PointerEvent): void {
    if (!armed) return

    const dx = e.clientX - downX
    const dy = e.clientY - downY

    if (!dragging) {
      if (Math.hypot(dx, dy) < DRAG_THRESHOLD_PX) return
      dragging = true
    }

    if (!camera || !domElement) return
    const lock = options.axisLock.value
    if (lock === null) return

    if (activeMode === 'translate') {
      const deltaWorld = projectPointerToAxis(
        camera,
        domElement,
        e.clientX,
        e.clientY,
        dragPlane,
        axisDirWorld,
        downHitWorld,
        scratch,
      )
      if (deltaWorld === null) return

      // 沿 axisDirWorld 方向移动 deltaWorld 米。
      // world 模式：axisDirWorld 是单位 X/Y/Z，只改对应轴。
      // local 模式：axisDirWorld 是倾斜方向（物体旋转后），三个世界轴分量都会变。
      const nx = startPos.x + axisDirWorld.x * deltaWorld
      const ny = startPos.y + axisDirWorld.y * deltaWorld
      const nz = startPos.z + axisDirWorld.z * deltaWorld

      // 写入 proxyGroup（内部会 sanitize + 触发 onLiveTransform → 线框跟手）
      options.transformProxy.writeProxyPosition(nx, ny, nz)
      return
    }

    if (activeMode === 'rotate') {
      /* ---------- rotate 分支（v1.3.0） ----------
       *
       * 鼠标绕"物体屏幕中心"的旋转角度 Δ → 写入 proxyGroup 的 yaw。
       *
       * 符号约定：
       *   CSS 坐标系 atan2：Y 轴朝下，顺时针为正。
       *   Three.js Y 轴旋转：Y 轴朝上，逆时针（右手螺旋）为正。
       *   CSS 顺时针 = Three.js Y 轴负方向旋转，故取负：newYaw = baseYaw - deltaAngle。
       *
       * cursor 视觉先行（compositor-only），再做 Three.js 写入（允许被丢帧）。
       */
      setCursor('rotate-arc')

      const rect = domElement.getBoundingClientRect()
      const px = e.clientX - rect.left
      const py = e.clientY - rect.top
      const currentScreenAngle = Math.atan2(py - screenCenter.y, px - screenCenter.x)
      const deltaAngle = currentScreenAngle - startScreenAngle

      // CSS 顺时针 → Three.js Y 轴逆时针（取负）
      const newYaw = baseYaw - deltaAngle
      options.transformProxy.writeProxyRotationY(newYaw)
      return
    }

    /* ---------- scale 分支 ----------
     *
     * 距离比：factor = distNow / distStart（Blender 标准）。
     * 起始距离 < 5px 时退化为线性 1 + |mouseDelta|/100。
     *
     * 锁定轴方向：业务约束永远 local（EV-011），但 scale 值本身就是 local 轴上的乘数，
     * proxyGroup.scale.x/y/z 天然对应物体的 local X/Y/Z，无需做 matrixWorld 分解。
     * 故只需：在锁定轴上乘 factor，其他轴保持 baseScale。
     *
     * 【v1.2.4 顺序调整】先写 cursor + 虚线（compositor 属性，走 GPU 合成线程），
     *   再做 writeProxyScale 的重活（Three.js 场景几何重建 + WebGL 提交）。
     *   根因：匀速拖动时 pointermove 高频触发，若先做 Three.js 重活，主线程被占满，
     *   后续的 style.transform 写入虽然本帧就提交，但浏览器会把它们批量推迟到下一帧
     *   甚至若干帧后才合成出来 → 用户观察到"松手后虚线慢慢追上"的尾帧效应。
     *   改为"视觉反馈先行"：即便 Three.js 这一帧被跳过，下一帧补上；但 cursor / 虚线
     *   保证每一帧都和鼠标严格同步，跟手体验对标 cursor。
     */
    const rect = domElement.getBoundingClientRect()
    const px = e.clientX - rect.left
    const py = e.clientY - rect.top
    const distNow = Math.hypot(px - screenCenter.x, py - screenCenter.y)
    const mouseDeltaPx = Math.hypot(dx, dy)

    /* v1.2.4：视觉反馈先行（cursor 是 compositor-only 属性） */
    const arrowAngle = computeArrowAngle(px, py, screenCenter.x, screenCenter.y)
    if (arrowAngle !== null) lastArrowAngleDeg = arrowAngle
    setCursor({ kind: 'axis-arrow', angleQ: quantizeAngleDeg(lastArrowAngleDeg) })

    /* Three.js 场景写入（重活，放最后——允许被浏览器丢帧，不阻塞视觉反馈） */
    const factor = computeScaleFactor(distStartPx, distNow, mouseDeltaPx)

    // 只改锁定轴；其他轴保持 baseScale。
    // sanitizeProxyTransform 会钉 MIN_DIMENSION 下限 + floor 的 Y 厚度，不用这里处理。
    const nx = lock === 'X' ? baseScale.x * factor : baseScale.x
    const ny = lock === 'Y' ? baseScale.y * factor : baseScale.y
    const nz = lock === 'Z' ? baseScale.z * factor : baseScale.z

    options.transformProxy.writeProxyScale(nx, ny, nz)
  }

  function onPointerUp(_e: PointerEvent): void {
    finishDrag(false)
  }

  function onKeyDown(e: KeyboardEvent): void {
    if (e.key === 'Escape') {
      e.preventDefault()
      e.stopPropagation()
      finishDrag(true)
    }
  }

  /** 右键按下 = 取消（Blender 约定；rollback 到 snapshot 不 commit） */
  function onContextMenu(e: MouseEvent): void {
    if (!armed) return
    e.preventDefault()
    e.stopPropagation()
    finishDrag(true)
  }

  function finishDrag(canceled: boolean): void {
    if (!armed) return

    if (canceled) {
      options.transformProxy.rollbackToSnapshot()
    } else if (dragging) {
      // 真拖拽发生过 → 一次 commit 到 sceneStore
      options.transformProxy.commitProxyToStore()
    }
    // 未拖拽（armed 但未越阈值）：既不 rollback 也不 commit —— 起始位置 == proxy 当前位置

    // 恢复 FlyCamera
    if (flyCameraController) {
      flyCameraController.setEnabled(wasFlyCameraEnabledBeforeDrag)
    }

    armed = false
    dragging = false
    setCursor(null)

    window.removeEventListener('pointermove', onPointerMove, true)
    window.removeEventListener('pointerup', onPointerUp, true)
    window.removeEventListener('keydown', onKeyDown, true)
    window.removeEventListener('contextmenu', onContextMenu, true)
    window.removeEventListener('mousedown', swallowMouse, true)
    window.removeEventListener('mousemove', swallowMouse, true)
    window.removeEventListener('mouseup', swallowMouse, true)
  }

  /* ============================================================
   * 安装到 sdk 的 dom
   * ============================================================ */

  let installedDom: HTMLElement | null = null

  function tryInstall(): void {
    if (!pullRuntime()) return
    if (installedDom === domElement) return
    if (installedDom) {
      installedDom.removeEventListener('pointerdown', onPointerDown, true)
      installedDom.removeEventListener('pointermove', onHoverMove, false)
      installedDom.removeEventListener('pointerleave', onPointerLeave, false)
    }
    domElement!.addEventListener('pointerdown', onPointerDown, true)
    domElement!.addEventListener('pointermove', onHoverMove, false)
    domElement!.addEventListener('pointerleave', onPointerLeave, false)
    installedDom = domElement
  }

  function onPointerLeave(): void {
    if (armed) return
    setCursor(null)
  }

  const stopWatchSdk = watch(
    () => options.sdk.value,
    () => {
      tryInstall()
    },
    { immediate: true },
  )

  const stopWatchSel = watch(
    () => [options.activeTool.value, options.selectedConfigKey.value, options.axisLock.value],
    () => {
      tryInstall()
      if (!armed && !shouldEngage()) {
        setCursor(null)
      }
    },
  )

  function dispose(): void {
    finishDrag(true)
    setCursor(null)
    if (installedDom) {
      installedDom.removeEventListener('pointerdown', onPointerDown, true)
      installedDom.removeEventListener('pointermove', onHoverMove, false)
      installedDom.removeEventListener('pointerleave', onPointerLeave, false)
      installedDom = null
    }
    stopWatchSdk()
    stopWatchSel()
    camera = null
    domElement = null
    flyCameraController = null
  }

  return { dispose, isPointerOnHighlight }
}
