<!--
  FloatingPanel — splat-studio 浮动面板基础组件

  设计要点：
  · 固定宽度（props.width）+ 高度上限（calc(100vh - 96px)）让面板不会随内容无限撑高
  · 内部采用 flex flex-col + min-h-0 三段结构（标题栏 shrink-0 / 内容 flex-1 overflow-hidden）
  · slot 内的滚动容器需用 `flex-1 min-h-0 overflow-y-auto` 才能正确滚动

  @changelog
  | 版本   | 变更说明                                                                                                  | 关联                                                                 |
  | v1.0.0 | 新增高度上限 maxHeight: calc(100vh - 96px)；Content 区域改为 flex-1 min-h-0 overflow-hidden，让内部滚动容器生效 | REQ: 20260427-创建驱动标注 UX 修订（HierarchyPanel 列表超长不滚动） |

  @author v_djlzhou
-->
<script setup lang="ts">
import { ref, computed, type Component } from 'vue'
import { IconCollapse, IconClose, IconMinimize } from '../../utils/icons'

const props = withDefaults(
  defineProps<{
    title: string
    icon?: Component
    position?: 'left-top' | 'left-bottom' | 'right'
    collapsed?: boolean
    visible?: boolean
    width?: number
  }>(),
  { collapsed: false, visible: true, width: 280 },
)

const emit = defineEmits<{
  'update:collapsed': [value: boolean]
  close: []
}>()

const isCollapsed = ref(props.collapsed)

function toggleCollapse() {
  isCollapsed.value = !isCollapsed.value
  emit('update:collapsed', isCollapsed.value)
}

const positionClass = computed(() => {
  switch (props.position) {
    case 'left-top':
      return 'top-3 left-3'
    case 'left-bottom':
      return 'bottom-[52px] left-3'
    case 'right':
      return 'top-3 right-3'
    default:
      return 'top-3 left-3'
  }
})
</script>

<template>
  <div
    v-if="visible"
    :class="[
      'absolute z-40 flex flex-col rounded-lg border border-border-strong overflow-hidden no-select',
      'bg-[#1a1a1d] shadow-panel',
      positionClass,
    ]"
    :style="{ width: `${width}px`, maxHeight: 'calc(100vh - 96px)' }"
  >
    <!-- Title bar -->
    <div
      :class="[
        'flex items-center justify-between h-8 px-3 bg-[#242428] border-b border-border shrink-0',
        isCollapsed ? 'cursor-pointer hover:bg-bg-hover transition-colors' : 'cursor-default',
      ]"
      @click="isCollapsed && toggleCollapse()"
    >
      <div class="flex items-center gap-2">
        <component v-if="icon" :is="icon" :size="14" class="text-accent" />
        <span class="text-xs font-semibold text-text-primary tracking-wide">{{ title }}</span>
      </div>
      <div class="flex items-center gap-0.5">
        <button
          class="flex items-center justify-center w-5 h-5 rounded text-text-subtle
                 hover:bg-bg-hover hover:text-text-primary transition-colors cursor-pointer
                 active:bg-bg-active"
          @click.stop="toggleCollapse"
        >
          <IconMinimize v-if="!isCollapsed" :size="12" />
          <IconCollapse v-else :size="12" />
        </button>
        <button
          class="flex items-center justify-center w-5 h-5 rounded text-text-subtle
                 hover:bg-danger/20 hover:text-danger transition-colors cursor-pointer
                 active:bg-danger/30"
          @click.stop="$emit('close')"
        >
          <IconClose :size="12" />
        </button>
      </div>
    </div>

    <!-- Content -->
    <div v-show="!isCollapsed" class="flex-1 min-h-0 p-3 overflow-hidden">
      <slot />
    </div>
  </div>
</template>
