/**
 * @changelog
 * | 版本   | 变更说明                                                                                                                                                       | 关联                                                                  |
 * | v1.0.0 | 初始实现：File → unknown → SceneExportConfig 的解析 + 类型守卫；三段式错误模型（PARSE / SCHEMA / VALIDATION）；rotation.y 归一化；数值 round2 兜底；导入流程与 sceneConfigExporter 镜像对称 | REQ: 文件菜单 — 导入场景配置                                          |
 * /@changelog
 *
 * @author v_djlzhou
 *
 * 场景配置导入器 — 把外部 JSON 文件解析为 SceneExportConfig。
 *
 * 三层错误模型（与 sceneConfigExporter 镜像对称的反向流程）:
 *   1. PARSE_ERROR      — JSON.parse 失败（语法错 / 文件不是 JSON）
 *   2. SCHEMA_ERROR     — JSON 合法但结构不符（必需字段缺失 / 类型错）
 *   3. VALIDATION_ERROR — 结构对但业务规则不通过（id 重复 / 必填空 / dimensions ≤ 0 等）
 *
 * 第 1/2 类是"无法继续"的硬错误，由本模块直接抛 ImportSceneConfigError；
 * 第 3 类复用 validateSceneConfig 的 ConfigValidationError[] 输出，调用方决策弹错误对话框。
 *
 * 设计原则:
 *   · 防御外部数据：所有字段都做"存在性 + 类型 + 范围"校验，缺一不可
 *   · 不静默回退：缺必填字段直接抛错，禁止用默认值掩盖（避免数据破损被忽视）
 *   · 数值规范化：position / dimensions 走 round2，rotation.y 走 normalizeRotationY
 *     —— 与 store 的 update actions 保持完全一致的输入清洗规则
 *   · 容忍多余字段：源文件可能含未来新增字段或注释字段（如 _comment），忽略不报错
 */

import type {
  SceneExportConfig,
  FloorConfigItem,
  PropConfigItem,
  PropCategory,
  Vec3Config,
  BoundsConfig,
} from '../types/scene-config'
import {
  PROP_CATEGORIES,
  round2,
  normalizeRotationY,
} from '../types/scene-config'
import {
  validateSceneConfig,
  type ConfigValidationError,
} from './sceneConfigValidator'

/* ============================================================
 * 错误类型
 * ============================================================ */

export type ImportErrorCode = 'PARSE_ERROR' | 'SCHEMA_ERROR'

export class ImportSceneConfigError extends Error {
  public readonly code: ImportErrorCode
  /** 原始底层错误（可选，用于排查） */
  public readonly cause?: unknown
  /** 字段路径（仅 SCHEMA_ERROR 提供） */
  public readonly path?: string

  constructor(code: ImportErrorCode, message: string, options?: { cause?: unknown; path?: string }) {
    super(message)
    this.name = 'ImportSceneConfigError'
    this.code = code
    this.cause = options?.cause
    this.path = options?.path
  }
}

/* ============================================================
 * 工具：类型守卫
 * ============================================================ */

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v)
}

function asNumber(v: unknown, path: string): number {
  if (typeof v !== 'number' || !Number.isFinite(v)) {
    throw new ImportSceneConfigError(
      'SCHEMA_ERROR',
      `${path} 应为有限数值，实际为 ${typeof v}`,
      { path },
    )
  }
  return v
}

function asString(v: unknown, path: string): string {
  if (typeof v !== 'string') {
    throw new ImportSceneConfigError(
      'SCHEMA_ERROR',
      `${path} 应为字符串，实际为 ${typeof v}`,
      { path },
    )
  }
  return v
}

function asObject(v: unknown, path: string): Record<string, unknown> {
  if (!isPlainObject(v)) {
    throw new ImportSceneConfigError(
      'SCHEMA_ERROR',
      `${path} 应为对象`,
      { path },
    )
  }
  return v
}

function asArray(v: unknown, path: string): unknown[] {
  if (!Array.isArray(v)) {
    throw new ImportSceneConfigError(
      'SCHEMA_ERROR',
      `${path} 应为数组`,
      { path },
    )
  }
  return v
}

/* ============================================================
 * 子结构解析
 * ============================================================ */

function parseVec3(raw: unknown, path: string): Vec3Config {
  const o = asObject(raw, path)
  return {
    x: round2(asNumber(o.x, `${path}.x`)),
    y: round2(asNumber(o.y, `${path}.y`)),
    z: round2(asNumber(o.z, `${path}.z`)),
  }
}

function parseBounds(raw: unknown, path: string): BoundsConfig {
  const o = asObject(raw, path)
  return {
    minX: round2(asNumber(o.minX, `${path}.minX`)),
    maxX: round2(asNumber(o.maxX, `${path}.maxX`)),
    minZ: round2(asNumber(o.minZ, `${path}.minZ`)),
    maxZ: round2(asNumber(o.maxZ, `${path}.maxZ`)),
  }
}

function parseFloorDimensions(raw: unknown, path: string): { width: number; depth: number } {
  const o = asObject(raw, path)
  return {
    width: round2(asNumber(o.width, `${path}.width`)),
    depth: round2(asNumber(o.depth, `${path}.depth`)),
  }
}

function parseFloor(raw: unknown, path: string): FloorConfigItem {
  const o = asObject(raw, path)
  return {
    id: asString(o.id, `${path}.id`),
    name: asString(o.name, `${path}.name`),
    // description 允许空串；缺失时视为空串（CLARIFY Q5 推断）
    description: typeof o.description === 'string' ? o.description : '',
    type: 'floor',
    position: parseVec3(o.position, `${path}.position`),
    dimensions: parseFloorDimensions(o.dimensions, `${path}.dimensions`),
    // v1.11.0 floor rotation 支持：可选字段，缺失时不带（运行时各处通过 ?.y ?? 0 兜底）
    ...(o.rotation &&
      typeof o.rotation === 'object' &&
      typeof (o.rotation as Record<string, unknown>).y === 'number'
      ? { rotation: { y: (o.rotation as Record<string, unknown>).y as number } }
      : {}),
  }
}

function parsePropCategory(raw: unknown, path: string): PropCategory {
  // 缺失或非字符串 → fallback 'decoration'（与 createDefaultProp 默认对齐）
  if (typeof raw !== 'string') return 'decoration'
  if ((PROP_CATEGORIES as string[]).includes(raw)) {
    return raw as PropCategory
  }
  // 字符串但不在白名单 → 直接抛错（明确告知，避免静默吞数据）
  throw new ImportSceneConfigError(
    'SCHEMA_ERROR',
    `${path} 取值 "${raw}" 不在合法分类内（${PROP_CATEGORIES.join('/')}）`,
    { path },
  )
}

function parseProp(raw: unknown, path: string): PropConfigItem {
  const o = asObject(raw, path)
  // rotation 兼容缺失（视为 { y: 0 }），兼容 number 形式（个别旧版本可能用裸数）
  let rotationY = 0
  if (o.rotation !== undefined) {
    if (typeof o.rotation === 'number') {
      rotationY = o.rotation
    } else {
      const ro = asObject(o.rotation, `${path}.rotation`)
      rotationY = asNumber(ro.y, `${path}.rotation.y`)
    }
  }
  const result: PropConfigItem = {
    id: asString(o.id, `${path}.id`),
    name: asString(o.name, `${path}.name`),
    description: typeof o.description === 'string' ? o.description : '',
    category: parsePropCategory(o.category, `${path}.category`),
    type: 'prop',
    position: parseVec3(o.position, `${path}.position`),
    dimensions: parseVec3(o.dimensions, `${path}.dimensions`),
    rotation: { y: normalizeRotationY(rotationY) },
  }
  return result
}

/* ============================================================
 * 顶层解析入口
 * ============================================================ */

/**
 * 把 unknown 解析为 SceneExportConfig。
 *
 * 仅做"结构 + 类型 + 数值规范化"，不做业务校验（id 唯一性等交给 validateSceneConfig）。
 *
 * @throws ImportSceneConfigError(SCHEMA_ERROR) 任何字段类型错或必填字段缺失
 */
export function parseSceneConfig(raw: unknown): SceneExportConfig {
  const root = asObject(raw, '$')

  const floorRaw = asArray(root.floor, '$.floor')
  const propRaw = asArray(root.prop, '$.prop')

  return {
    sceneId: asString(root.sceneId, '$.sceneId'),
    name: asString(root.name, '$.name'),
    description: typeof root.description === 'string' ? root.description : '',
    bounds: parseBounds(root.bounds, '$.bounds'),
    floor: floorRaw.map((f, i) => parseFloor(f, `$.floor[${i}]`)),
    prop: propRaw.map((p, i) => parseProp(p, `$.prop[${i}]`)),
  }
}

/**
 * 从 File 对象一站式导入：read text → JSON.parse → parseSceneConfig → validateSceneConfig。
 *
 * 返回值含 config 与 validationErrors：
 *   · validationErrors.length === 0 → 调用方可直接 replaceSceneConfig(config)
 *   · validationErrors.length > 0   → 调用方应弹错误对话框，不写入 store
 *
 * 解析期硬错误（PARSE / SCHEMA）通过 throw 上抛，因为这两类错代表"文件根本不是合法配置"，
 * 没有任何可用的 partial config 给调用方选择。
 *
 * @throws ImportSceneConfigError(PARSE_ERROR)  JSON 不合法
 * @throws ImportSceneConfigError(SCHEMA_ERROR) JSON 合法但结构/类型错
 */
export async function importSceneConfigFromFile(
  file: File,
): Promise<{ config: SceneExportConfig; validationErrors: ConfigValidationError[] }> {
  let text: string
  try {
    text = await file.text()
  } catch (e) {
    throw new ImportSceneConfigError(
      'PARSE_ERROR',
      `读取文件失败：${(e as Error)?.message ?? String(e)}`,
      { cause: e },
    )
  }

  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch (e) {
    throw new ImportSceneConfigError(
      'PARSE_ERROR',
      `JSON 解析失败：${(e as Error)?.message ?? String(e)}`,
      { cause: e },
    )
  }

  const config = parseSceneConfig(raw)
  const validationErrors = validateSceneConfig(config)
  return { config, validationErrors }
}

/**
 * 把 ImportSceneConfigError 格式化为面向用户的错误文本。
 * 用于硬错误（PARSE / SCHEMA）的简易提示（不进 ExportErrorDialog 复用流程）。
 */
export function formatImportError(err: ImportSceneConfigError): string {
  const head = err.code === 'PARSE_ERROR' ? '文件解析失败' : '配置结构不符'
  const where = err.path ? `（${err.path}）` : ''
  return `${head}${where}：${err.message}`
}
