/**
 * usePersistentHighlight — 已标实体常驻线框订阅式 composable
 *
 * 封装 PersistentHighlightRenderer 的：
 *   · 实例化（setup，在 sceneReady 后调用）
 *   · 4 处响应式 watch（sceneConfig / selectedConfigKey / enabled 开关）
 *   · 生命周期清理（teardown，在 teardownViewerSDK 时调用）
 *
 * Viewport.vue 侧只需调用 2 个方法（setup / teardown），零内部 watch 泄漏。
 *
 * @changelog
 * | 版本   | 变更说明                                                    | 关联               |
 * | v1.0.0 | 初始实现：封装持久高亮的 watch + 生命周期，Viewport.vue 仅增 4 行 | REQ: 大场景标注辅助 |
 * | v1.1.0 | 随 viewer-sdk sdk/index.ts v2.0.0 删除 getScene/getCamera 转发，改走 helper getSdkThreeContext(sdk) 从 ECS state 直读；语义等价 | REQ: 20260707-scene-manager-ecs-getter-cleanup |
 * /@changelog
 *
 * @author v_djlzhou
 */
import { watch, type Ref } from 'vue'
import type { ViewerSDK } from '@tencent/viewer-sdk'
import { useSceneStore } from '../stores/scene'
import { useEditorStore } from '../stores/editor'
// v1.1.0：sdk 层 v2.0.0 删除 getScene/getCamera 转发，改走 helper 走 ECS 直读
import { getSdkThreeContext } from '../utils/sdkThreeContext'
import { PersistentHighlightRenderer } from './useSelection/persistent-highlight-renderer'

export interface UsePersistentHighlightOptions {
  sdk: Ref<ViewerSDK | null>
}

export interface UsePersistentHighlightHandle {
  /**
   * 在 sceneManager.onSceneReady 回调内调用（紧跟 selection.trySetup() 之后）。
   *
   * 会从 sdk 取 Three.js scene/camera，构造 PersistentHighlightRenderer，
   * 注册 watch，并执行首次 syncAll()。
   *
   * 重复调用安全（已初始化时直接返回）。
   */
  setup: () => void
  /**
   * 在 teardownViewerSDK 时调用。
   *
   * 停止所有 watch，dispose renderer（释放所有 WebGL 资源），
   * 将 renderer 置 null。
   */
  teardown: () => void
}

export function usePersistentHighlight(
  options: UsePersistentHighlightOptions,
): UsePersistentHighlightHandle {
  const sceneStore = useSceneStore()
  const editorStore = useEditorStore()

  let renderer: PersistentHighlightRenderer | null = null
  // 存储 watch 停止句柄，teardown 时统一停止
  const stopHandles: Array<() => void> = []

  function syncAll(): void {
    if (!renderer) return

    if (!editorStore.persistentHighlightEnabled) {
      renderer.setVisible(false)
      return
    }
    renderer.setVisible(true)

    // 构造 excludeIds：当前选中实体在选中层渲染，持久层不重复画
    const excludeIds = new Set<string>()
    if (sceneStore.selectedConfigKey) {
      excludeIds.add(sceneStore.selectedConfigKey.id)
    }

    renderer.sync(
      sceneStore.sceneConfig.floor,
      sceneStore.sceneConfig.prop,
      excludeIds,
    )
  }

  function setup(): void {
    const sdk = options.sdk.value
    if (!sdk) return
    // 幂等：已初始化则跳过
    if (renderer) return

    // v1.1.0：从 helper 一次拿三件套（ECS 直读 rendererModule/cameraModule state，与 useSelection.trySetup 同源）
    const { camera, scene } = getSdkThreeContext(sdk)
    if (!camera || !scene) return

    renderer = new PersistentHighlightRenderer({ scene, camera })

    // 注册 3 处 watch，停止句柄统一收集
    // ⚠️ 顺序约束：Viewport.vue 中 watch(selectedConfigKey) 先于本 composable 注册
    //   （Viewport mount 早于 onSceneReady），Vue watch FIFO 保证选中层先更新（添加强色），
    //   本 composable 后更新（移除弱色），任何帧被操作实体至少有 1 个线框。
    stopHandles.push(
      // sceneConfig deep watch：floor/prop 增删改都会触发
      watch(() => sceneStore.sceneConfig, syncAll, { deep: true }),
      // 选中态变化：excludeIds 变化 → 对应实体在两层间切换
      watch(() => sceneStore.selectedConfigKey, syncAll),
      // 开关切换
      watch(() => editorStore.persistentHighlightEnabled, syncAll),
    )

    // 首次同步
    syncAll()
  }

  function teardown(): void {
    // 停止所有 watch
    stopHandles.forEach((stop) => stop())
    stopHandles.length = 0
    // 释放 WebGL 资源
    renderer?.dispose()
    renderer = null
  }

  return { setup, teardown }
}

